#!/usr/bin/env python3
"""Enrich every existing worked solution on all 8 classes (teacher request 2026-11-11):
- fix display leaks: '\\boxed{!' (exact-blank marker) and the placeholder latex '\\text{method}'
- 'Working:' steps get a real instruction (EN + AR)
- every step without a 'why' gets one, chosen by what the step does (substitute, factor, divide, check, ...)
- common short instructions and the final answer lines get Arabic ('ar')
Steps that already carry why/ar (generated by steps-grade9-10.py) are left unchanged.
usage: python3 scripts/steps-enrich.py [--write]
"""
import json, re, sys
from pathlib import Path
